import math
from itertools import permutations

def is_square(n):
    if n < 0:
        return False
    root = int(math.isqrt(n))
    return root * root == n

def check_cool(n):
    # Use backtracking search (DFS) to find a valid permutation

    def solve(path, used, current_sum):
        if len(path) == n:
            # Found a complete permutation
            return path[:]

        for next_num in range(1, n + 1):
            if next_num not in used:
                new_sum = current_sum + next_num

                if not is_square(new_sum):
                    # Try this path
                    used.add(next_num)
                    path.append(next_num)

                    result = solve(path, used, new_sum)

                    if result is not None:
                        return result

                    # Backtrack
                    path.pop()
                    used.remove(next_num)

        return None

    # Try starting with every possible number
    for start_num in range(1, n + 1):
        if not is_square(start_num):
            # Check if the first element itself is not a square
            path = [start_num]
            used = {start_num}

            result = solve(path, used, start_num)

            if result is not None:
                return result

    return None

print("--- Testing Cool Integers (n=1 to 20) ---")
cool_integers = []
results = {}

for n in range(1, 21):
    permutation = check_cool(n)

    if permutation:
        results[n] = {"cool": True, "permutation": permutation}
        cool_integers.append(n)

        # Calculate partial sums for reporting
        sums = []
        current_sum = 0
        for x in permutation:
            current_sum += x
            sums.append(current_sum)
        results[n]["sums"] = sums

        print(f"n={n}: COOL. Permutation: {permutation}. Partial Sums: {sums}")
    else:
        results[n] = {"cool": False}
        print(f"n={n}: NOT COOL.")

